$ErrorActionPreference='Stop'
$credText = ("protocol=https" + [Environment]::NewLine + "host=github.com" + [Environment]::NewLine + [Environment]::NewLine) | git credential fill
$tokenLine = $credText | Where-Object { $_ -like 'password=*' } | Select-Object -First 1
if (-not $tokenLine) { throw 'Git credential manager did not return a GitHub credential.' }
$token = $tokenLine.Substring(9)
$headers = @{ Authorization = "Bearer $token"; Accept = "application/vnd.github+json"; "X-GitHub-Api-Version" = "2026-03-10" }
function Get-Api([string]$Label,[string]$Uri) {
  Write-Output ("=== " + $Label + " ===")
  try { (Invoke-RestMethod -Method Get -Headers $headers -Uri $Uri) | ConvertTo-Json -Depth 12 -Compress }
  catch { Write-Output ("HTTP_ERROR=" + $_.Exception.Response.StatusCode.value__ + " " + $_.Exception.Message) }
}
Get-Api 'ACTIONS_PERMISSIONS' 'https://api.github.com/repos/fengie/mhw-mods/actions/permissions'
